// Logical asset src ("candies/bubs/hero.png") -> responsive <picture> sources from public/img
// (generated by `npm run images`). Build-time only.
import { readFileSync } from 'node:fs';

type Entry = { w: number; h: number; widths: number[]; license: string | null };
let index: Record<string, Entry> | null = null;
function load(): Record<string, Entry> {
  if (!index) {
    try {
      index = JSON.parse(readFileSync('public/img/index.json', 'utf8'));
    } catch {
      throw new Error('public/img/index.json missing: run `npm run images`');
    }
  }
  return index!;
}

export type ImgSources = { webp: string; png: string; fallback: string; width: number; height: number };

/** `displayWidth` = CSS px the image renders at; srcset covers 1x/2x via `sizes`. */
export function img(src: string, displayWidth: number): ImgSources {
  const e = load()[src];
  if (!e) throw new Error(`No generated image for "${src}" (missing asset, or reference-only in a public build)`);
  const base = `/img/${src.replace(/\.png$/, '')}`;
  const set = (fmt: string) => e.widths.map((w) => `${base}-${w}.${fmt} ${w}w`).join(', ');
  const fb = e.widths.find((w) => w >= displayWidth * 2) ?? e.widths[e.widths.length - 1];
  return { webp: set('webp'), png: set('png'), fallback: `${base}-${fb}.png`, width: e.w, height: e.h };
}

export const hasImg = (src: string | null | undefined): src is string => !!src && !!load()[src];
